import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山雷颐","description":"周易折中 - 山雷颐","frontmatter":{"title":"山雷颐","description":"周易折中 - 山雷颐"},"headers":[],"relativePath":"zh/classics/zhezhong/033.md","filePath":"zh/classics/zhezhong/033.md"}'),h={name:"zh/classics/zhezhong/033.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山雷颐" tabindex="-1">山雷颐 <a class="header-anchor" href="#山雷颐" aria-label="Permalink to “山雷颐”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>颐序卦：物畜然后可养，故受之以颐。夫物既畜聚，则必有以养之，无养则不能存息。颐所以次大畜也。卦上艮下震，上下二阳爻中含四阴，上止而下动，外实而中虚，人颐颔之象也。颐，养也。人口所以饮食养人之身，故名为颐。圣人设卦推养之义，大至于天地养育万物，圣人养贤以及万民，与人之养生、养形、养德、养人，皆颐养之道也。动息节宣以养生也，饮食衣服以养形也，威仪行义以养德也，推己及物以养人也。</p><p>颐：贞吉，观颐，自求口实</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>颐，口旁也，口食物以自养，故为养义。为卦上下二阳内含四阴，外实内虚，上止下动，为颐之象。养之义贞吉者，占者得正则吉。观颐，谓观其所养之道；自求口实，谓观其所以养身之术，皆得正则吉也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>颐之道，以正则吉也。人之养身、养德、养人、养于人，皆以正道则吉也。天地造化，养育万物，各得其宜者，亦正而已矣。观颐自求口实，观人之所颐与其自求口实之道，则善恶吉凶可见矣。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类云 ：养须是正则吉，观颐是观其养德正不正，自求口实是观其养身正不正。未说到养人处。</p></li><li><p>林氏希元曰 ：人之所养有二，一是养性，一是养身，二者皆不可不正。观其所养之道，如大学圣贤之道正也，异端小道则不正矣。又必自求其口实，如重道义而略口体正也，急口体而轻道义则不正矣。皆正则吉，不正则凶。</p></li><li><p>陈氏琛曰 ：集义以养其气，寡欲以养其心，守圣道而不溺于虚无，崇圣学而不流于术数，则所以养德者正矣。穷而不屑于呼蹴，达而不至于素餐，不以贫贱饥渴害其心，不以声色臭味汩其性，则所以养身者正矣。</p></li><li><p>陆氏铨曰 ：观颐即考其善不善，自求口实即于己取之而已矣。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>陆氏说与传义异，盖云观其所养者以自求养而已。如所养者德乎，则当自求其所以养德之道；如所养者身乎，则当自求其所以养身之方。与夫子《彖传》语意尤合也。</p><p>象曰：山下有雷，颐；君子以愼言语，节饮食</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>二者，养德养身之切务。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>以二体言之，山下有雷，雷震于山下，山之生物皆动其根荄，发其萌芽，为养之象。以上下之义言之，艮止而震动，上止下动，颐颔之象。以卦形言之，上下二阳中含四阴，外实中虚，颐口之象。口所以养身也，故君子观其象以养其身，愼言语以养其德，节饮食以养其体。不唯就口取养义，事之至近而所系至大者，莫过于言语饮食也。在身为言语，于天下则凡命令政教出于身者皆是，愼之则必当而无失。在身为饮食，于天下则凡货资财用养于人者皆是，节之则适宜而无伤。推养之道，养德养天下莫不然也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：或云“谚有‘祸从口出，病从口入’，甚好。曰：此语前辈曾用以解颐之象。愼言语，节饮食。</p></li><li><p>冯氏椅曰 ：“法雷之动以愼其所出，法山之止以节其所入。”</p></li><li><p>赵氏汝梅曰 ：“雷之声为言语，山之养为饮食。言语饮食出入乎颐者也。”</p></li><li><p>俞氏琰曰 ：“颐乃口颊之象，故取其切于颐者言之曰‘愼言语，节饮食’。充此言语之类，则凡号令政教之出于己者，皆所当愼而不可悖出。充此饮食之类，则凡货财赋税之入于上者，皆所当节而不可悖入。”</p></li></ul><p>彖曰：颐贞吉，养正则吉也；观颐，观其所养也；自求口实，观其自养也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>贞吉，所养者正则吉也。所养，谓所养之人与养之之道。自求口实，谓其自求养身之道，皆以正则吉也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏舜臣曰：古之观人，每每观其所养。而所养之大小，则必以其所自养者观之。夫重道义之养而略口体，此养之大者也；急口体之养而轻道义，此养之小者也。养其大体则为大人，养其小体则为小人。天之赋予，初无小大之别，而人之所养各殊，则其所成就者亦异。</p></li><li><p>谷氏家杰曰：观颐者，当于所养观之，又当于所养中自养处观之。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>李氏、谷氏说皆得孟子考其善不善之意。</p><p>天地养万物，圣人养贤以及万民，颐之时大矣哉</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>极言养道而赞之。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>圣人极言颐之道而赞其大。天地之道，则养育万物。养育万物之道，正而已矣。圣人作养贤才，与之共天位，使之食天禄，俾施泽于天下，养贤以及万民也。养贤所以养万民也。夫天地之中，品物之众，非养则不生。圣人裁成天地之道，辅相天地之宜，以养天下，至于鸟兽草木，皆有养之之政。其道配天地，故夫子推颐之道，赞天地与圣人之功曰：“颐之时大矣哉！”或云义，或云用，或止云时，以其大者也。万物之生与养，时为大，故云时。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>赵氏汝梅曰：圣人之于万民，岂能家与之粟而人与之衣？其急先务者，亦曰养贤而已。贤得所养，则仁恩自及于百姓矣。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>卦有曰尚贤、养贤者，皆是六五上九相遇，如大有、大畜、颐、鼎等卦。此卦颐为养义，而六五又赖上九之养以养人，故曰“圣人养贤以及万民”也。</p><p>初九：舍尔灵龟，观我朵颐，凶</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>灵龟，不食之物。朵，垂也。朵颐，欲食之貌。初九阳刚在下，足以不食，乃上应六四之阴而动于欲，凶之道也。故其象占如此。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>蒙之初六，蒙者也，爻乃主发蒙而言。颐之初九，亦假外而言尔。谓初也，舎尔之灵龟，乃观我而朵颐。我对尔而设。初之所以朵颐者，四也。然非四谓之也，假设之辞耳。九阳体刚明，其才智足以养正者也。龟能咽息不食，灵龟喻其明智而可以不求养于外也。才虽如是，然以阳居动体，而在颐之时，求颐人所欲也。上应于四，不能自守，志在上行，说所欲而朵颐者也。心既动，则其自失必矣。迷欲而失己，以阳而从阴，则何所不至，是以凶也。朵颐为朵，动其颐颔，人见食而欲之，则动颐垂涎，故以为象。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：朵颐者，嚼也。以阳处下而为动始，不能令物由己养，动而求养者也。夫安身莫若不竞，修己莫若自保。守道则福至，求禄则辱来。居养贤之世，不能贞其所履以全其德，而舎其灵龟之明兆，羡我朵颐而躁求，凶莫甚焉。</p></li><li><p>苏氏轼曰 ：养人者阳也，养于人者阴也。君子在上，足以养人；在下，足以自养。初九以一阳而伏于四阴之下，其德足以自养而无待于物者如龟也。不能守之而观于四，见其可欲，朵颐而慕之，为阴之所致也，故凶。</p></li><li><p>郑氏汝谐曰 ：颐之上体皆吉，而下体皆凶。上体止也，下体动也。在上而止，养人者也；在下而动，求养于人者也。动而求养于人者，必累于口体之养，故虽以初之刚阳，未免于动其欲而观朵颐也。</p></li><li><p>何氏楷曰 ：初与上阳刚之德同而吉凶不同者，初为动之主，上为止之主。养道宜静，故也。</p></li></ul><h3 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to “附录”">​</a></h3><ul><li>项氏安世曰 ：颐卦惟有二阳，上九在上，谓之由颐，固为所养之主。初九在下，亦足为自养之贤。灵龟伏息而在下，初九之象也。朵颐在上而下垂，上九之象也。上九为卦之主，故称我。群阴从我而求养，固其所也。初九本无所求，乃亦仰而观我，有灵而不自保，有贵而不自珍，宜其凶也。初九本灵本贵，圣人以其为动之主，居养之初，故深戒之以明自养之道。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>项氏以“观我朵颐”为上九亦备一说。</p><p>象曰：观我朵颐，亦不足贵也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>九动体朵颐，谓其说阴而志动，既为欲所动，则虽有刚健明智之才，终必自失，故其才亦不足贵也。人之贵乎刚者，为其能立而不屈于欲也；贵乎明者，为其能照而不失于正也。既惑所欲而失其正，何刚明之有为可贱也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰 ：明其本有良贵，今观夫朵颐，则失其所谓贵矣。</p></li><li><p>俞氏琰曰 ：孟子云：“养其大体为大人，养其小体为小人。”又云：“饮食之人则人贱之矣。”今初九阳德之大本，有可贵之质，乃内舍其大，而外观其小，岂不为人所贱？故曰“亦不足贵也”。</p></li></ul><p>六二：颠颐拂经于丘颐，征凶</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>求养于初，则颠倒而违于常理；求养于上，则往而得凶。丘，土之高者，上之象也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>女不能自处，必从男；阴不能独立，必从阳。二阴柔不能自养，待养于人者也。天子养天下，诸侯养一国，臣食君上之禄，民赖司牧之养，皆以上养下，理之正也。二既不能自养，必求养于刚阳。若反下求于初，则为颠倒，故云颠颐。颠则拂违经常，不可行也。若求养于丘，则往必有凶。丘在外而高之物，谓上九也。卦止二阳，既不可颠颐于初，若求颐于上九，往则有凶。在颐之时，相应则相养者也。上非其应而往求养，非道妄动，是以凶也。颠颐则拂经，不获其养尔，妄求于上，往则得凶也。今有人才不足以自养，见在上者𫝑力足以养人，非其族类，妄往求之，取辱得凶必矣。六二中正在他卦多吉而凶，何也？曰：时然也。阴柔既不足以自养，初上二爻皆非其与，故往求则悖理而得凶也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰 ：二五得位得中，而不能自养，反由颐于无位之爻，与常经相悖，故皆为拂经。上艮体，故为于丘。</p></li><li><p>黄氏干曰 ：颐之六爻，只是颠拂二字。求养于下则为颠，求养于上则为拂。六二比初而求上，故“颠颐”当为句，“拂经于丘颐”为句，“征凶”则其占辞也。六三拂颐，虽与上为正应，然是求于上以养己，故凶。六四颠颐，固与初为正应，然是赖初之养以养人，故虽颠而吉。六五拂经，是比于上，然是赖上九之养以养人，所以居贞而亦吉。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>项氏、黄氏说深得文意，可从。本义虽从程传以“征凶”属之“丘颐”，然至其解《象传》“六二征凶，行失类也”，则曰“初上皆非其类也”，则亦以“征凶”总承两义矣。</p><p>象曰：六二征凶，行失类也</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>初上皆非其类也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>征而从上则凶者，非其类故也。往求而失其类，得凶宜矣。行，往也。</p><p>六三：拂颐贞凶，十年勿用，无攸利</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>阴柔不中正，以处动极，拂于颐矣。既拂于颐，虽正亦凶，故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>颐之道，惟正则吉。三以阴柔之质而处不中正，又在动之极，是柔邪不正而动者也。其养如此，拂违于颐之正道，是以凶也。得颐之正则所养皆吉，求养养人则合于义，自养则成其德。三乃拂违正道，故戒以“十年勿用”，十数之终，谓终不可用，无所往而利也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰 ：履邪好动，系说于上，不但拂颐之经而已，害颐之正莫甚焉，故凶。</p></li><li><p>杨氏时曰 ：颐正则吉，六三不中正而居动之极，拂颐之正也。十年勿用，则终不可用矣，何利之有？</p></li><li><p>郑氏汝谐曰 ：三应于上，若得所养而凶莫甚于三，盖不中不正而居动之极，所以求养于人者必无所不至，是谓拂于颐之正，凶之道也。十年勿用，无攸利，戒之也。因其多欲妄动，示之以自反之理，作易之本意也。</p></li></ul><p>象曰：十年勿用，道大悖也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>所以戒终不可用，以其所由之道大悖义理也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰 ：“拂颐贞”三字当连读。颐之卦辞曰：“颐贞吉。”三之爻辞曰：“拂颐贞凶。”卦中惟此一爻与卦义相反，故曰“道大悖也”。</li></ul><p>六四：颠颐吉，虎视眈眈，其欲逐逐，无咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>柔居上而得正，所应又正，而赖其养以施于下，故虽颠而吉。虎视眈眈，下而专也；其欲逐逐，求而继也。又能如是，则无咎矣。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四在人上，大臣之位。六以阴居之，阴柔不足以自养，况养天下乎？初九以刚阳居下，在下之贤也，与四为应。四又柔顺而正，是能顺于初，赖初之养也。以上养下则为顺，今反求下之养，颠倒也，故曰颠颐。然已不胜其任，求在下之贤而顺从之以济其事，则天下得其养而已，无旷败之咎，故为吉也。夫居上位者，必有才德威望，为下民所尊畏，则事行而众心服从。若或下易其上，则政出而人违，刑施而怨起，轻于陵犯，乱之由也。六四虽能顺从刚阳，不废厥职，然质本阴柔，赖人以济。人之所轻，故必养其威严。耽耽然如虎视，则能重其体貌，下不敢易。又从于人者，必有常。若间或无继，则其政败矣。其欲谓所须用者，必逐逐相继而不乏，则其事可济。若取于人而无继，则困穷矣。既有威严，又所施不穷，故能无咎也。二颠颐则拂经，四则吉，何也？曰：二在上而反求养于下，下非其应类，故为拂经；四则居上位以贵下贱，使在下之贤由己以行其道，上下之志相应而施于民，何吉如之？自三以下养口体者也，四以上养德义者也。以君而资养于臣，以上位而赖养于下，皆养德也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰 ：自初而言之，则初之见养于四为凶；自四言之，则四之得养初九为吉。</p></li><li><p>游氏酢曰 ：以上养下，颐之正也。若在上而反资养于下，则于颐为倒置矣。此二与四所以俱为颠颐也。然二之志在物，而四之志在道，故四颠颐而吉，而二则征凶也。</p></li><li><p>朱子语类问音辩载马氏曰 ：眈眈，虎下视貌，则当为下而专矣。又问其欲逐逐如何，曰：求于下以养人，必当继继求之，不厌乎数，然后可以养人而不穷。</p></li><li><p>呉氏澄曰 ：自养于内者莫如龟，求养于外者莫如虎。故颐之初九、六四取二物为象。四之于初，其下贤求益之心必如虎之视下求食而后可。其视下也专一而不他，其欲食也继续而不歇，如是则于人不贰，于己不自足，乃得居上求下之道。</p></li><li><p>林氏希元曰 ：苟下贤之心不专，则贤者不乐告以善道；求益之心不继，则才有所得而遽自足。</p></li></ul><p>象曰：顚颐之吉，上施光也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>顚倒求养而所以吉者，盖得刚阳之应以济其事，致己居上之德施光明被于天下，吉孰大焉。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>谷氏家杰曰 ：养逮于下，则上施光，是养贤及民也。</li></ul><p>六五：拂经居贞吉，不可涉大川</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>六五阴柔不正，居尊位而不能养人，反赖上九之养，故其象占如此。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五，颐之时，居君位，养天下者也。然其阴柔之质，才不足以养天下。上有刚阳之贤，故顺从之，赖其养己以济天下。君者，养人者也，反赖人之养，是违拂于经常。既以己之不足而顺从于贤师傅上，师傅之位也，必居守贞固，笃于委信，则能辅翼其身，泽及天下，故吉也。阴柔之质，无贞刚之性，故戒以能居贞则吉。以阴柔之才，虽倚赖刚质，能持循于平时，不可处艰难变故之际，故云“不可涉大川”也。以成王之才，不至甚柔弱也，当管蔡之乱，几不保于周公，况其下者乎？故书曰：“王亦未敢诮公。”赖二公得终信，故艰险之际，非刚明之主不可恃也。不得已而济艰险者，则有矣，发此义者，所以深戒于为君也。于上九，则据为臣致身尽忠之道言，故不同也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>丘氏富国曰 ：豫五不言豫，以豫由乎四也；颐五不言颐，以颐由乎上也。</p></li><li><p>林氏希元曰 ：不能养人而反赖上九以养于人，故其象为拂经，言反常也。然在己不能养人而赖贤者以养，亦正道也，故居贞而吉。若不用人而自用，则任大责重，终不能胜，如涉大川终不能济，故不可。</p></li></ul><p>象曰：居贞之吉，顺以从上也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>居贞之吉者，谓能坚固顺从于上九之贤以养天下也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>张氏清子曰 ：五能柔顺以从上九之贤，赖之以养天下，真圣人养贤以及万民之事也。</li></ul><p>上九：由颐厉吉，利涉大川</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>六五赖上九之养以养人，是物由上九以养也。位高任重，故厉而吉。阳刚在上，故利涉川。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上九以刚阳之德，居师傅之任，六五之君柔顺而从于己，赖己之养，是当天下之任，天下由之以养也。以人臣而当是任，必常怀危厉，则吉也。如伊尹、周公何尝不忧勤兢畏，故得终吉。夫以君之才不足而倚赖于己，身当天下大任，宜竭其才力，济天下之艰危，成天下之治安，故曰“利涉大川”。得君如此之专，受任如此之重，苟不济天下艰危，何足称委遇而谓之贤乎？当尽诚竭力而不顾虑，然惕厉则不可忘也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰 ：以阳处上而履四阴，阴不能独为主，必宗于阳也，故莫不由之以得其养。</p></li><li><p>李氏舜臣曰 ：豫九四曰“由豫”者，即由颐之谓也。“由豫”在四，犹下于五也，而已有可疑之迹；“由颐”在上，则过中而嫌于不安，故厉。</p></li><li><p>丘氏富国曰 ：阳实阴虚，实者养人，虚者求人之养。故四阴皆求养于阳者。然养之权在上，是二阳爻又以上为主，而初阳亦求养者也，故直于上九一爻曰“由颐”焉。</p></li></ul><p>象曰：由颐厉吉，大有庆也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>若上九之当大任，如是能兢畏，如是天下被其德泽，是大有福庆也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰 ：豫之九四，天下由之以豫，故曰“大有得”。颐之上九，天下由之以颐，故曰“大有庆”。</p></li><li><p>项氏安世曰 ：六五、上九二爻皆当以小象解之。六五之“居贞”，非自守也，贞于从上也，故曰“居贞之吉，顺以从上也”。上九之“厉吉”，非能自吉也，得六五之委任而吉也，故曰“由颐厉吉，大有庆也”。</p></li></ul><p>总论</p><p>呉氏曰 ：慎曰养之为道，以养人为公，养己为私。自养之道，以养德为大，养体为小。艮三爻皆养人者，震三爻皆养己者。初九、六二、六三皆自养口体，私而小者也；六四、六五、上九皆养其德以养人，公而大者也。公而大者吉，得颐之正也；私而小者凶，失颐之贞也。可不观颐而自求其正耶？</p>',117)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
